    def setup_Enivronment(self):
        for _ in range(25):
            pos1 = random.randint(0,24)
            pos2 = random.randint(0,49)

            if self.gridValues[pos1][pos2] == "." and self.gridValues[pos1][pos2] != "#":
                self.gridValues[pos1][pos2] = "$"

        for _ in range(25):
            pos1 = random.randint(0, 24)
            pos2 = random.randint(0, 49)

            if self.gridValues[pos1][pos2] == "." and self.gridValues[pos1][pos2] != "#" and self.gridValues[pos1][pos2] != "$":
                self.gridValues[pos1][pos2] = "W"

    def output_Enivronment(self):
        for line in self.grid:
            print(line)
        time.sleep(0.75)

    def coordinate_Converter(self, humanX, humanY):
        return (50 - humanY, humanX - 1)





